				"query": "index=\"corelight\" sourcetype=\"corelight_conn\" suri_ids{}=*\n| fields uid, ts, orig_bytes, resp_bytes, service, local_orig, local_resp, id.orig_h, id.orig_p, id.resp_h, id.resp_p, suri_ids{}\n| mvexpand suri_ids{}\n| eval suri_id='suri_ids{}', ts=ts\n| join type=inner suri_id\n    [ search index=\"corelight\" sourcetype=\"corelight_suricata_corelight\"\n      | fields suri_id, alert.signature_id, alert.signature, uid\n      | rename alert.signature_id as sid, alert.signature as signature]\n\n| lookup corelight_detection_enrichment.csv sid OUTPUT sid as lookup_sid impact_score category technique_number attack_phase suri_rule technique_name sub_technique_name sub_technique_number attack_reason traffic_direction cve_number cve_creation_date cve_impact_score cve_exploitability_score cve_description impact_score_reason tags\n| eval in_lookup=if(isnull(lookup_sid), \"no\", \"yes\") \n| search in_lookup=\"yes\"\n| fillnull value=\"N/A\" lookup_sid impact_score category technique_number attack_phase suri_rule technique_name sub_technique_name sub_technique_number attack_reason traffic_direction cve_number cve_creation_date cve_impact_score cve_exploitability_score cve_description impact_score_reason tags\n| where impact_score > 3 \n\n| join type=left uid\n    [ search index=\"corelight\" sourcetype=\"corelight_dns\"\n      | stats values(answers{}) as answers_list, values(qtype_name) as qtype_name_list, values(rcode_name) as rcode_name_list by uid\n    ]\n\n| join type=left uid\n    [ search index=\"corelight\" sourcetype=\"corelight_files\"\n      | stats values(md5) as md5_list, values(sha256) as sha256_list, values(rx_hosts{}) as rx_hosts_list, values(filename) as filename_list, values(mime_type) as mime_type_list, values(seen_bytes) as seen_bytes_list by uid\n      ]\n\n| join type=left uid\n    [ search index=\"corelight\" sourcetype=\"corelight_http\"\n      | stats values(method) as method_list, values(user_agent) as user_agent_list, values(uri) as uri_list, values(client_headers) as client_headers_list, values(host) as host_list, values(status_code) as status_code_list by uid\n       ]\n\n| join type=left uid\n  [ search index=\"corelight\" sourcetype=\"corelight_ssl\"\n   | stats values(subject) as subject_list, values(cert_chain_fps{}) as cert_chain_fps_list, values(server_name) as server_name_list, values(issuer) as issuer_list, values(validation_status) as validation_status_list by uid\n  ]\n\n| join type=left uid\n    [ search index=\"corelight\" sourcetype=\"corelight_smb_mapping\"\n      | stats values(file_path_root) as smb_path by uid\n    ]\n\n| stats values(sid) as sids, values(signature) as signature, values(answers_list) as answers_list, values(qtype_name_list) as qtype_names, values(rcode_name_list) as rcode_names, values(md5_list) as md5_list, values(sha256_list) as sha256, values(rx_hosts_list) as rx_hosts_list, values(filename_list) as filename, values(mime_type_list) as mime_type_list, values(seen_bytes_list) as seen_bytes_list, values(method_list) as method_list, values(user_agent_list) as user_agent_list, values(uri_list) as uri_list, values(client_headers_list) as client_headers_list, values(host_list) as host_list, values(status_code_list) as status_code_list, values(subject) as subject_list, values(cert_chain_fps_list) as cert_chain_fps_list, values(server_name_list) as server_name_list, values(issuer_list) as issuer_list, values(validation_status_list) as validation_status_list, values(smb_path) as smb_path_list, values(attack_phase) as attack_phases, values(impact_score) as impact_scores, values(category) as categories, values(technique_number) as technique_numbers, values(suri_rule) as suri_rules, values(technique_name) as technique_names, values(sub_technique_name) as sub_technique_names, values(sub_technique_number) as sub_technique_numbers, values(attack_reason) as attack_reasons, values(traffic_direction) as traffic_directions, values(cve_number) as cve_numbers, values(cve_creation_date) as cve_creation_dates, values(cve_impact_score) as cve_impact_scores, values(cve_exploitability_score) as cve_exploitability_scores, values(cve_description) as cve_descriptions, values(impact_score_reason) as impact_score_reasons, values(tags) as tags, values(ts) as ts_list, values(orig_bytes) as orig_bytes_list, values(resp_bytes) as resp_bytes_list, values(service) as service_list, values(local_orig) as local_orig_list, values(local_resp) as local_resp_list, values(id.orig_h) as orig_h_list, values(id.orig_p) as orig_p_list, values(id.resp_h) as resp_h_list, values(id.resp_p) as resp_p_list by uid \n| eval ts=strftime(strptime(ts_list, \"%Y-%m-%dT%H:%M:%S.%6N%Z\"), \"%Y-%m-%d %H:%M:%S\")\n| eval d_type=case(\n    isnotnull(sids), \"Suricata\",\n    sourcetype==\"corelight_intel\", \"Intel\",\n    sourcetype==\"notice\", \"Notice\",\n    true(), \"Unknown\"\n)\n\n| eval seen = mvappend(\"corelight_conn\",\n  if(isnotnull(answers_list) OR isnotnull(qtype_names) OR isnotnull(rcode_names), \"corelight_dns\", null()),\n  if(isnotnull(md5_list) OR isnotnull(rx_hosts_list) OR isnotnull(sha256) OR isnotnull(filename) OR isnotnull(mime_type_list) OR isnotnull(seen_bytes_list), \"corelight_files\", null()),\n  if(isnotnull(method_list) OR isnotnull(user_agent_list) OR isnotnull(uri_list),\"corelight_http\", null()),\n  if(isnotnull(subject_list) OR isnotnull(cert_chain_fps_list) OR isnotnull(issuer_list) OR isnotnull(validation_status_list), \"corelight_ssl\", null()), \n  if(isnotnull(smb_path_list), \"corelight_smb_mapping\", null()))\n| eval seen = mvfilter(isnotnull(seen))\n",
				"enableSmartSources": true,
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
