		"ds_BM7jZdrv": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_evt_aggregations`  did=\"$did$\"\n| eval sid = mvappend(sid, 'sid{}')\n| eval signature = mvappend(signatures, 'signatures{}')\n| lookup corelight_alert_aggregations sid OUTPUT sid as lookup_sid impact_score category technique_number attack_phase technique_name sub_technique_name sub_technique_number attack_reason traffic_direction cve_number cve_creation_date cve_impact_score cve_exploitability_score cve_description impact_score_reason tags\n| eval in_lookup=if(isnull(lookup_sid), \"no\", \"yes\")\n| search in_lookup=\"yes\"\n| table *",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
