		"ds_xAanw4qb": {
			"type": "ds.search",
			"options": {
				"enableSmartSources": true,
				"query": "index=\"corelight\" sourcetype=\"corelight_detections5\"\n| eval normalized_sid=coalesce('sid{}', sid)\n| mvexpand normalized_sid\n| rename normalized_sid as sid\n\n| join type=left sid\n    [ search index=\"corelight\" sourcetype=\"corelight_suricata_corelight\"\n      | rename alert.signature_id as sid, alert.signature as signature\n      | fields suri_id, sid, signature\n      ]\n|  lookup corelight_detection_enrichment2.csv sid OUTPUT impact_score attack_phase category technique_number technique_name traffic_direction sub_technique_name, sub_technique_number, attack_reason, traffic_direction, cve_number, cve_creation_date, cve_impact_score, cve_exploitability_score, cve_description, impact_score_reason, tags\n| where impact_score > 3\n\n| search did=$did$\n| dedup sid\n| table sid impact_score signature attack_phase category technique_number technique_name traffic_direction\n| sort - impact_score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "alert_aggregations_details_top_list"
		},
		"ds_brGcXi0I": {
			"type": "ds.search",
			"options": {
				"query": "index=\"corelight\" sourcetype=\"corelight_detections5\" did=$did$\n| eval sid = mvappend(sid, 'sid{}')\n| eval signature = mvappend(signature, 'signature{}')\n| eval paths = mvappend(paths, 'paths{}')\n| rex field=paths \"(?<=corelight_)(?<last_part>\\w+)\"\n| eval ts = strftime(strptime(ts, \"%Y-%m-%dT%H:%M:%S.%6NZ\"), \"%m-%d-%Y %H:%M:%S\")\n| dedup uid\n| eventstats values(uid) as all_uids\n| eval tokenuids = mvjoin(all_uids, \",\")\n| table uid ts id.orig_h id.resp_h \n| rename uid as uid, ts as Timestamp, id.orig_h as Source, id.resp_h as Destination",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_uid_list"
		},
		"ds_4IWGGYU7": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx`\n| eval source=\"$source$\"\n| eval target_sourcetype = case(\n    source==\"conn\", \"corelight_conn\",\n    source==\"http\", \"corelight_http\",\n    source==\"ssl\", \"corelight_ssl\",\n    source==\"dns\", \"corelight_dns\",\n    source==\"files\", \"corelight_files\",\n    source==\"smb\", \"corelight_smb_mapping\"\n)\n| where sourcetype = target_sourcetype \n| search uid = $uid$\n| eval spcap_link = \"<a href=\\\"\" . 'spcap.url' . \"\\\" target=\\\"_blank\\\">\" . 'spcap.url' . \"</a>\"\n",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_events_dynamic_display"
		},
		"ds_SI79AqlY": {
			"type": "ds.search",
			"options": {
				"enableSmartSources": true,
				"query": "index=\"corelight\" sourcetype=\"corelight_detections5\" uid=$uid$\n| eval paths = mvappend(paths, 'paths{}')\n| eval \n    Conn = if(match(paths, \"corelight_conn\"), 1, 0),\n    HTTP = if(match(paths, \"corelight_http\"), 1, 0),\n    SSL = if(match(paths, \"corelight_ssl\"), 1, 0),\n    DNS = if(match(paths, \"corelight_dns\"), 1, 0),\n    Files = if(match(paths, \"corelight_files\"), 1, 0),\n    SMB = if(match(paths, \"corelight_smb_mapping\"), 1, 0)\n| stats values(tokenuids), max(Conn) as Conn, max(HTTP) as HTTP, max(SSL) as SSL, max(DNS) as DNS, max(Files) as Files, max(SMB) as SMB",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
