		"ds_mht8x8sn": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_st_suricata` uid=$uid$ \n| eval clicked_value=\"$payloadtoken$\"\n| where clicked_value=\"available\"\n| fields payload, uid, alert.signature_id\n| rename alert.signature_id as sid\n| eval decoded_payload = if(isnotnull(sid) AND (isnull(payload) OR payload==\"\"), \"No payload available\", null())\n| where isnotnull(sid)\n| eval converts=split(payload,\"\")\n|  lookup corelight_base64conversion index as converts OUTPUT value as base64bin\n| eval bin_combined=mvjoin(base64bin,\"\")\n| eval bin_chunked=split(replace(bin_combined, \"(.{8})\", \"\\1,\"), \",\") \n| lookup corelight_base64conversion index as bin_chunked OUTPUT value as ascii\n| rex field=ascii mode=sed \"s/\\~/ /g\"\n| eval decoded_payload = if(isnull(decoded_payload), mvjoin(ascii,\"\"), decoded_payload)\n| eval combined = sid + \":::\" + coalesce(payload, \"\") + \":::\" + decoded_payload\n| stats values(combined) as combined_values by uid\n| mvexpand combined_values\n| eval sid=mvindex(split(combined_values, \":::\"), 0)\n| eval payload=mvindex(split(combined_values, \":::\"), 1)\n| eval decoded_payload=mvindex(split(combined_values, \":::\"), 2)\n| stats list(sid) as SIDs, list(decoded_payload) as \"Decoded Payloads\" by uid payload\n| fields SIDs, \"Decoded Payloads\"",
				"queryParameters": {
					"earliest": "-48h@h",
					"latest": "now"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_payloads"
		},
		"ds_OIBg5giw": {
			"type": "ds.search",
